27	const PARTS = ["What I concluded", "How I know", "What I could not establish", "What happens next"];
28	const ALT: Record<string, string[]> = {
29	  "What I concluded": ["結論", "依据", "未能确定", "接下来"],
30	};
31	
32	function split(report: string): { part: string; chars: number }[] {
33	  const marks: { part: string; at: number }[] = [];
34	  for (const part of PARTS) {
35	    for (const spelling of [part, ...(ALT[part] ?? [])]) {
36	      const re = new RegExp(`(^|\\n)#{1,3}[^\\n]*${spelling}`, "g");
37	      let m: RegExpExecArray | null;
38	      while ((m = re.exec(report))) marks.push({ part, at: m.index + (m[1] ? 1 : 0) });
39	    }
40	  }
41	  marks.sort((a, b) => a.at - b.at);
42	  const out: { part: string; chars: number }[] = [];
43	  if (marks.length === 0) return [{ part: "(no contract headings)", chars: report.length }];
44	  if (marks[0].at > 0) out.push({ part: "(before the first heading)", chars: marks[0].at });
45	  for (let i = 0; i < marks.length; i += 1) {
46	    const end = i + 1 < marks.length ? marks[i + 1].at : report.length;
47	    out.push({ part: marks[i].part, chars: end - marks[i].at });
48	  }
49	  return out;
50	}
